const r = $input.first().json.report || {};
const t = r.totals || {};
const byCat = Array.isArray(r.by_category) ? r.by_category : [];
const byTrade = Array.isArray(r.by_trade) ? r.by_trade : [];
const recent = Array.isArray(r.recent_pending) ? r.recent_pending : [];

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function money(n) { return n != null && n > 0 ? Number(n).toLocaleString('es-ES', {minimumFractionDigits: 2}) + ' EUR' : '-'; }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }

const rowsRecent = recent.map(i => `<tr style="background:${i.days_waiting > 14 ? '#fee' : (i.days_waiting > 5 ? '#fff8e0' : '#fff')}">
  <td>${esc(i.supplier_name || '?')}</td>
  <td>${esc(i.invoice_number || '-')}</td>
  <td>${esc(i.project_name)}</td>
  <td>${esc(i.category || '-')} / ${esc(i.trade_type || '-')}</td>
  <td>${dateShort(i.invoice_date)}</td>
  <td style="text-align:right;font-weight:600">${money(i.total_amount)}</td>
  <td style="text-align:right;font-weight:600">${i.days_waiting}d</td>
</tr>`).join('');

const rowsCat = byCat.map(c => `<tr><td>${esc(c.category)}</td><td style="text-align:right">${c.pending_count}</td><td style="text-align:right;font-weight:600">${money(c.amount_pending)}</td></tr>`).join('');
const rowsTrade = byTrade.map(c => `<tr><td>${esc(c.trade_type)}</td><td style="text-align:right">${c.total_count}</td><td style="text-align:right;color:#e67e22">${c.pending}</td><td style="text-align:right;color:#27ae60">${c.paid}</td><td style="text-align:right;color:#c00">${c.disputed}</td><td style="text-align:right">${money(c.avg_amount)}</td></tr>`).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Invoices Overview - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}.sub{color:#888;font-size:13px;margin-bottom:24px}
  h2{margin:32px 0 12px;font-size:18px;border-bottom:1px solid #ddd;padding-bottom:6px}
  .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:14px}
  .card h3{margin:0 0 4px;font-size:11px;color:#666;text-transform:uppercase;letter-spacing:.5px}
  .card .v{font-size:22px;font-weight:600}
  .card .sub{font-size:12px;color:#888;margin-top:4px}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden;font-size:13px}
  th,td{padding:8px 10px;border-bottom:1px solid #eee;text-align:left}
  th{background:#f0f0f3;font-weight:600;font-size:11px;text-transform:uppercase;color:#555}
  tr:last-child td{border-bottom:none}
  .row-grid{display:grid;grid-template-columns:1fr 1.5fr;gap:18px}
  .meta{font-size:12px;color:#888;margin-top:24px}
  @media (max-width:900px){.cards{grid-template-columns:repeat(2,1fr)} .row-grid{grid-template-columns:1fr}}
</style></head><body>
<h1>Invoices Overview - ArquitAI</h1>
<p class="sub">Vista agregada de facturas (proveedores). Para vigilancia: cron_invoice_approval_followup diario 11:30.</p>
<div class="cards">
  <div class="card"><h3>Pending review</h3><div class="v" style="color:${t.count_pending > 0 ? '#e67e22' : '#27ae60'}">${t.count_pending || 0}</div><div class="sub">${money(t.amount_pending)}</div></div>
  <div class="card"><h3>Approved sin pagar</h3><div class="v">${t.count_approved_unpaid || 0}</div><div class="sub">${money(t.amount_approved_unpaid)}</div></div>
  <div class="card"><h3>Pagadas 30d</h3><div class="v" style="color:#27ae60">${t.count_paid || 0}</div><div class="sub">${money(t.amount_paid_30d)}</div></div>
  <div class="card"><h3>Disputed</h3><div class="v" style="color:${t.count_disputed > 0 ? '#c00' : '#666'}">${t.count_disputed || 0}</div></div>
</div>
<div class="row-grid">
  <div>
    <h2>Pending por categoria</h2>
    <table><thead><tr><th>cat</th><th style="text-align:right">n</th><th style="text-align:right">amount</th></tr></thead><tbody>${rowsCat || '<tr><td colspan="3" style="text-align:center;color:#888;padding:14px">Sin pending</td></tr>'}</tbody></table>
  </div>
  <div>
    <h2>Por gremio (historico)</h2>
    <table><thead><tr><th>gremio</th><th style="text-align:right">total</th><th style="text-align:right">pending</th><th style="text-align:right">paid</th><th style="text-align:right">disp</th><th style="text-align:right">avg</th></tr></thead><tbody>${rowsTrade || '<tr><td colspan="6" style="text-align:center;color:#888;padding:14px">Sin facturas</td></tr>'}</tbody></table>
  </div>
</div>
<h2>Pending review (cola, mas antiguas primero)</h2>
<table><thead><tr><th>supplier</th><th>numero</th><th>proyecto</th><th>cat/gremio</th><th>fecha</th><th style="text-align:right">importe</th><th style="text-align:right">esperando</th></tr></thead><tbody>${rowsRecent || '<tr><td colspan="7" style="text-align:center;color:#888;padding:14px">Sin facturas pending</td></tr>'}</tbody></table>
<div class="meta">Generado ${new Date().toISOString()}</div>
</body></html>`;

return [{ json: { html } }];
